use std::{fs,path::PathBuf};
use nutbook_backend::commands::native_presentation::{audience_init_script,live_preview_init_script};
fn main(){let args:Vec<_>=std::env::args().collect();let dir=PathBuf::from(&args[1]);let static_motion=args.get(2).is_some_and(|s|s=="static");let restore=args.get(2).filter(|_|!static_motion).map(|path|serde_json::from_str(&fs::read_to_string(path).unwrap()).unwrap());let seq=args.get(3).map(|s|s.parse().unwrap()).unwrap_or(0);let generation=if restore.is_some(){2}else{1};fs::create_dir_all(&dir).unwrap();fs::write(dir.join("audience.js"),audience_init_script("motion-test",1,"opening",generation,"zh-CN",restore.as_ref(),seq,!static_motion,static_motion)).unwrap();fs::write(dir.join("mirror.js"),live_preview_init_script("motion-test","opening",restore.as_ref(),static_motion)).unwrap();}
